// TypeScript module

interface NotificationPayload = EmailPayload | SmsPayload | PushPayload

type EmailPayload = { type: 'email', to: string, subject: string, body: string }
type SmsPayload = { type: 'sms', phoneNumber: string, message: string }
type PushPayload = { type: 'push', deviceToken: string, title: string, body: string }

interface NotificationResult { success: boolean; messageId?: string; error?: string }

interface Notifier { send(payload: NotificationPayload): Promise<NotificationResult> }

// Shared helper (not a base class)
async function sendRequest(config: {apiUrl, apiKey}, path: string, body: object): Promise<NotificationResult>
  response = await fetch(config.apiUrl + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${config.apiKey}` },
    body: JSON.stringify(body)
  })
  if !response.ok: return { success: false, error: response.statusText }
  data = await response.json()
  return { success: true, messageId: data.messageId }

const createEmailNotifier = (config): Notifier => ({
  send: async (payload: EmailPayload) => sendRequest(config, '/email', payload)
})

const createSmsNotifier = (config): Notifier => ({
  send: async (payload: SmsPayload) => sendRequest(config, '/sms', payload)
})

const createPushNotifier = (config): Notifier => ({
  send: async (payload: PushPayload) => sendRequest(config, '/push', payload)
})

class CompositeNotifier implements Notifier {
  private notifiers: Map<string, Notifier>  // keyed by payload type

  constructor(notifiers: Map):
    this.notifiers = notifiers

  async send(payload: NotificationPayload): Promise<NotificationResult>
    notifier = this.notifiers.get(payload.type)
    if !notifier: return { success: false, error: `unsupported type: ${payload.type}` }
    return notifier.send(payload)
}

export function createNotificationService(config: { apiUrl: string; apiKey: string }): CompositeNotifier
  map = new Map([
    ['email', createEmailNotifier(config)],
    ['sms', createSmsNotifier(config)],
    ['push', createPushNotifier(config)]
  ])
  return new CompositeNotifier(map)
